class Solution {
public:
    vector<int> intersection(vector<int>& nums1, vector<int>& nums2) {
        set<int> a(nums1.begin(), nums1.end()), both;
        for (int i = 0; i < (int)nums2.size(); i++) {
            if (a.count(nums2[i])) both.insert(nums2[i]);
        }
        return vector<int>(both.begin(), both.end());
    }
};
